	o.onLeaveButtonPressed = function()
	{
		try { ::CareerStats.cacheNakedPortraits(); }
		catch (e) { ::logWarning("CareerStats: Failed to cache portraits on town leave — " + e); }
		return onLeaveButtonPressed();
	}
});

