// Incremental naked-portrait cache: only renders brothers who have not been cached yet
// or whose face/body/hair/beard/tattoo/permanent-injury sprites changed (e.g. Barber or injury).
::CareerStats._portraitSignature <- function( _bro )
{
	local sigLayers = ["body", "head", "hair", "beard", "beard_top", "tattoo_body", "tattoo_head",
		"permanent_injury_1", "permanent_injury_2", "permanent_injury_3", "permanent_injury_4"];
	local sig = "";
	foreach (layer in sigLayers)
	{
		try
		{
			local sprite = _bro.getSprite(layer);
			sig += (sprite != null && sprite.HasBrush ? sprite.getBrush().Name : "") + "|";
		}
		catch (e) { sig += "|"; }
	}
	return sig;
}

// Shared function to cache naked portraits for living brothers needing a fresh snapshot
::CareerStats.cacheNakedPortraits <- function( _forceAll = false )
{
	local equipmentLayers = [
		"armor", "armor_upgrade_back", "armor_upgrade_front",
		"helmet", "helmet_damage", "surcoat",
		"accessory", "accessory_special", "shaft", "quiver",
		"body_blood", "dirt", "injury", "injury_body",
		"bandage_1", "bandage_2", "bandage_3"
	];
	local bodyLayers = ["head", "hair", "beard", "beard_top", "tattoo_head"];

	local allBros = ::World.getPlayerRoster().getAll();
	local bros = [];
	local sigs = [];
	foreach (bro in allBros)
	{
		if (bro == null) continue;
		local sig = ::CareerStats._portraitSignature(bro);
		if (!_forceAll && "m" in bro
			&& "CareerStats_CachedPortrait" in bro.m && bro.m.CareerStats_CachedPortrait != ""
			&& "CareerStats_CachedSig" in bro.m && bro.m.CareerStats_CachedSig == sig)
			continue;
		bros.push(bro);
		sigs.push(sig);
	}
	if (bros.len() == 0)
		return;

	local savedEquipment = [];
	local savedVisibility = [];
	local savedItems = [];

	// PASS 1: Unequip weapons
	foreach (bro in bros)
	{
		try
		{
			local items = bro.getItems();
			local mainhand = items.getItemAtSlot(::Const.ItemSlot.Mainhand);
			local offhand = items.getItemAtSlot(::Const.ItemSlot.Offhand);
			if (mainhand != null)
			{
				savedItems.push({ bro = bro, slot = ::Const.ItemSlot.Mainhand, item = mainhand });
				items.unequip(mainhand);
			}
			if (offhand != null)
			{
				savedItems.push({ bro = bro, slot = ::Const.ItemSlot.Offhand, item = offhand });
				items.unequip(offhand);
			}
		}
		catch (e) {}
	}

	// PASS 2: Strip armor brushes
	foreach (bro in bros)
	{
		try
		{
			foreach (layer in equipmentLayers)
			{
				try
				{
					local sprite = bro.getSprite(layer);
					if (sprite != null && sprite.HasBrush)
					{
						savedEquipment.push({ bro = bro, layer = layer, brushName = sprite.getBrush().Name });
						sprite.resetBrush();
					}
				}
				catch (e2) {}
			}

			foreach (layer in bodyLayers)
			{
				try
				{
					local sprite = bro.getSprite(layer);
					if (sprite != null && !sprite.Visible)
					{
						savedVisibility.push({ bro = bro, layer = layer, wasVisible = false });
						sprite.Visible = true;
					}
				}
				catch (e2) {}
			}

			bro.setDirty(true);
		}
		catch (e) {}
	}

	// Cache naked portrait paths
	foreach (i, bro in bros)
	{
		try
		{
			if ("CareerStats_CachedPortrait" in bro.m)
			{
				bro.m.CareerStats_CachedPortrait = bro.getImagePath();
				bro.m.CareerStats_CachedPortraitX = bro.getImageOffsetX();
				bro.m.CareerStats_CachedPortraitY = bro.getImageOffsetY();
			}
			else
			{
				bro.m.CareerStats_CachedPortrait <- bro.getImagePath();
				bro.m.CareerStats_CachedPortraitX <- bro.getImageOffsetX();
				bro.m.CareerStats_CachedPortraitY <- bro.getImageOffsetY();
			}
			if ("CareerStats_CachedSig" in bro.m)
				bro.m.CareerStats_CachedSig = sigs[i];
			else
				bro.m.CareerStats_CachedSig <- sigs[i];
		}
		catch (e) {}
	}

	// Restore everything
	foreach (saved in savedEquipment)
	{
		try
		{
			local sprite = saved.bro.getSprite(saved.layer);
			if (sprite != null) sprite.setBrush(saved.brushName);
		}
		catch (e) {}
	}
	foreach (saved in savedVisibility)
	{
		try
		{
			local sprite = saved.bro.getSprite(saved.layer);
			if (sprite != null) sprite.Visible = saved.wasVisible;
		}
		catch (e) {}
	}
	foreach (saved in savedItems)
	{
		try { saved.bro.getItems().equip(saved.item); }
		catch (e) {}
	}
	foreach (bro in bros)
	{
		try { bro.setDirty(true); } catch(e) {}
	}

	::logWarning("CareerStats: Cached naked portraits for " + bros.len() + "/" + allBros.len() + " brothers");
}

// Hook town LEAVE only — incremental cache for newly hired or barber/injury-changed brothers
::mods_hookNewObjectOnce("ui/screens/world/modules/world_town_screen/town_main_dialog_module", function (o)
{
	local onLeaveButtonPressed = o.onLeaveButtonPressed;
	o.onLeaveButtonPressed = function()
	{
		try { ::CareerStats.cacheNakedPortraits(false); }
		catch (e) { ::logWarning("CareerStats: Failed to cache portraits on town leave — " + e); }
		return onLeaveButtonPressed();
	}
});
